    Particle& p = particles[i];

    // Integrate velocity (apply gravity)
    p.vy += g * deltaTime;

    // Integrate position
    p.x += p.vx * deltaTime;
    p.y += p.vy * deltaTime;

    // Boundary conditions: X-axis
    if (p.x < -boxWidth) {
        p.x = -boxWidth;
        p.vx *= -elasticity;
    } else if (p.x > boxWidth) {
        p.x = boxWidth;
        p.vx *= -elasticity;
    }

    // Boundary conditions: Y-axis
    if (p.y < -boxWidth) {
        p.y = -boxWidth;
        p.vy *= -elasticity;
    } else if (p.y > boxWidth) {
        p.y = boxWidth;
        p.vy *= -elasticity;
    }
}
